-- Recipes for the 45 dishes in the owner's "La Roca Dishes and quantities" reference.
-- Ingredient quantities are estimates: the source lists things like "1 portion", "1 tbsp",
-- "1 leaf" rather than weights, so they're converted onto the inventory's tracked units
-- (kg/Ltr/Pc/Bunch) using documented per-unit assumptions. These can be tuned later without
-- any app changes -- only the numbers in recipe_ingredients need to change.

-- Hide restaurant items not in the new dish list (kept intact: history, recipes, everything --
-- just no longer offered to waiters). Manager can re-show any of these later.
update public.menu_items set active = false where line = 'restaurant' and name in (
  'Avocado Salad',
  'Avocado Sandwich',
  'Avocado Wrap',
  'Beef Steak',
  'Beignet',
  'Boiled Sweet Potatoes & Veg',
  'Bread Roll',
  'Broccoli Steak',
  'Brown Bread',
  'Bun',
  'Chef Salad',
  'Chimichurri Steak',
  'Fish Omelets',
  'Fish Vegetable Soup',
  'Goat Brochette',
  'Grilled Banana',
  'Grilled Chicken Wrap',
  'Grilled Potato',
  'La Roca Bread',
  'Pasta Salad',
  'Plain Omelette',
  'Plain Sandwich',
  'Samosa',
  'Seasonal Salad',
  'Stuffed Chicken',
  'Zingalo'
);

-- The reference splits this into two separate dishes; keep the existing row as "Ugali"
